import{_ as o,a8 as l,o as r,c as n,ah as s,K as a}from"./chunks/framework.DwkUJ0oD.js";import"./chunks/theme.DXFaLrA7.js";const u=JSON.parse('{"title":"主动回忆法","description":"","frontmatter":{"title":"主动回忆法","abstract":"主动回忆法的核心流程与 13 种记忆提取练习——大脑倾倒、闪卡、闭卷总结、模拟考试等，用主动输出替代被动重读。","created":"2026-07-02T00:00:00.000Z","tags":["学习方法","记忆技巧","检索练习"],"type":"步骤操作","related":["[[📚 个人知识管理-MOC]]","[[搭建知识体系：七大学习模型]]"],"reference":null,"category":["📚 个人知识管理","个人能力"]},"headers":[],"relativePath":"vault/Knowledge/Methods/主动回忆法.md","filePath":"vault/Knowledge/Methods/主动回忆法.md","lastUpdated":1790655645000}'),_={name:"vault/Knowledge/Methods/主动回忆法.md"};function d(c,e,h,p,m,b){const i=l("NolebaseGitContributors"),t=l("NolebaseGitChangelog");return r(),n("div",null,[e[0]||(e[0]=s('<h1 id="主动回忆法" tabindex="-1">主动回忆法 <a class="header-anchor" href="#主动回忆法" aria-label="Permalink to “主动回忆法”">​</a></h1><h2 id="核心过程-重复" tabindex="-1">核心过程（重复） <a class="header-anchor" href="#核心过程-重复" aria-label="Permalink to “核心过程（重复）”">​</a></h2><p>学习概念 → 合上资料 → 回忆所有能想到的内容 → 核对遗漏 → 填补空白</p><p>目标：<strong>输出知识</strong>——被动重读不如主动测试</p><h2 id="_13-种记忆提取法" tabindex="-1">13 种记忆提取法 <a class="header-anchor" href="#_13-种记忆提取法" aria-label="Permalink to “13 种记忆提取法”">​</a></h2><ol><li>进行限时大脑倾倒：设定3到5分钟，把所有内容写出来</li><li>讲解知识点：卡壳的地方就是知识缺口</li><li>做记忆思维导图：只用脑袋里的知识，之后查看资料并找出错误</li><li>闭卷写总结：凭记忆写完整的总结，之后打开资料，找出错误</li><li>凭借记忆写出解题步骤清单</li><li>自问自答：学习时随手写下，学完后靠脑中知识解答</li><li>闪卡记忆法：每张只记一个知识点或步骤，翻卡前先回忆，答得差不多也是错</li><li>选择性删减：将关键词隐藏，凭借记忆还原</li><li>单页总结：把整个主题评记忆压缩成一页 <ol><li>分成3到5个主要板块：概念定义、核心公式、重要观点、步骤、易错点、示例</li><li>每个板块写3到5个关键词提示，外加一个迷你案例和常见错误</li><li>示例： <ol><li>流程：画迷你流程图</li><li>概念：列个简易对比表，A与B与C的区别</li></ol></li><li>最好留白，后面可以进行补充，如果写不下就是内容太臃肿了</li></ol></li><li>录制音频：用自测问答的题目直接录答案，每个问题录一段，即兴发挥不能看资料</li><li>截图挑战：拍下整洁的笔记或思维导图，然后凭记忆重构</li><li>模拟考试场景做一份试卷</li><li>考前30分钟回忆知识点</li></ol>',6)),a(i),a(t)])}const C=o(_,[["render",d]]);export{u as __pageData,C as default};
